INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('후시미이나리 대사', '伏見稲荷大社', 'SHRINE_TEMPLE', '京都府', '京都市伏見区', 34.967140, 135.772672, 'ALWAYS', NULL, NULL, NULL, '경내는 24시간, 授与所 8:30~16:30', NULL, '전국 약 3만 곳 이나리 신사의 총본궁. 붉은 도리이가 산길을 따라 끝없이 이어지는 센본토리이로 유명하다.', '정상까지 왕복 2시간쯤. 이른 아침이나 해 질 녘이 한산하다.', NULL, 'https://inari.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('기요미즈데라', '清水寺', 'SHRINE_TEMPLE', '京都府', '京都市東山区', 34.994856, 135.785046, 'FIXED', '06:00', '18:00', NULL, '닫는 시간은 계절에 따라 다름. 봄·여름·가을 야간 특별 배관 있음', '500엔', '못을 하나도 쓰지 않고 절벽 위에 세운 "기요미즈의 무대"로 유명한 세계유산 사찰. 무대에서 교토 시내가 한눈에 들어온다.', '본당 아래 오토와 폭포 물은 세 줄기 중 하나만 마시는 것이 관례.', NULL, 'https://www.kiyomizudera.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('긴카쿠지 (로쿠온지)', '金閣寺（鹿苑寺）', 'SHRINE_TEMPLE', '京都府', '京都市北区', 35.039370, 135.729243, 'FIXED', '09:00', '17:00', NULL, NULL, '500엔', '금박을 입힌 3층 누각 사리전이 연못 경호지에 비치는 세계유산 사찰. 연못에 비친 "거꾸로 금각"이 명물.', '입장권이 부적 모양이라 기념으로 챙겨 가자.', NULL, 'https://www.shokoku-ji.jp/kinkakuji/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('긴카쿠지 (지쇼지)', '銀閣寺（慈照寺）', 'SHRINE_TEMPLE', '京都府', '京都市左京区', 35.027020, 135.798245, 'FIXED', '08:30', '17:00', NULL, '12/1~3/14는 9:00~16:30', '1,000엔 (2026년 4월부터)', '아시카가 요시마사의 산장을 절로 바꾼 곳. 소박한 은각과 하얀 모래를 쌓은 은사탄·향월대가 와비사비의 멋을 보여준다.', '철학의 길 북쪽 끝이라 이어서 걷기 좋다.', NULL, 'https://www.shokoku-ji.jp/ginkakuji/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('야사카 신사', '八坂神社', 'SHRINE_TEMPLE', '京都府', '京都市東山区', 35.003656, 135.778553, 'ALWAYS', NULL, NULL, NULL, '경내 24시간. 授与所 9:00~17:00', NULL, '기온 마쓰리를 여는 기온의 수호 신사. 밤에도 등불이 켜진 붉은 누문이 시조 거리 끝에서 반겨준다.', '밤 참배도 가능해서 기온 산책 마무리로 좋다.', NULL, 'https://www.yasaka-jinja.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도지', '東寺', 'SHRINE_TEMPLE', '京都府', '京都市南区', 34.980528, 135.747755, 'FIXED', '08:00', '17:00', NULL, '금당·강당 기준 (마지막 입장 16:30). 경내는 5:00~17:00', NULL, '헤이안 시대부터 이어진 진언종 총본산. 높이 약 55m로 일본에서 가장 높은 목조탑인 오층탑이 교토역 근처에 서 있다.', '매달 21일에는 경내에 큰 벼룩시장(고보상)이 선다.', NULL, 'https://toji.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('산주산겐도', '三十三間堂', 'SHRINE_TEMPLE', '京都府', '京都市東山区', 34.987968, 135.771734, 'FIXED', '08:30', '17:00', NULL, '11/16~3/31은 9:00~16:00. 마지막 입장 30분 전', '600엔', '길이 약 120m의 본당 안에 천수관음상 1001체가 늘어선 절. 끝없이 이어진 불상 행렬이 압도적이다.', '본당 안은 촬영 금지.', NULL, 'https://www.sanjusangendo.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('헤이안 신궁', '平安神宮', 'SHRINE_TEMPLE', '京都府', '京都市左京区', 35.015999, 135.782437, 'FIXED', '06:00', '18:00', NULL, '경내 기준. 신원(정원)은 8:30부터, 닫는 시간은 계절별 (600엔)', NULL, '헤이안 천도 1100년을 기념해 세운 신궁. 거대한 붉은 대도리이와 궁궐을 본뜬 건물이 시원하게 펼쳐진다.', '봄에는 신원의 수양벚꽃이 특히 아름답다.', NULL, 'https://www.heianjingu.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('난젠지', '南禅寺', 'SHRINE_TEMPLE', '京都府', '京都市左京区', 35.011370, 135.794316, 'ALWAYS', NULL, NULL, NULL, '경내 자유. 방장정원·삼문은 8:40~17:00 (12~2월 16:30)', NULL, '거대한 삼문과 붉은 벽돌 수로각(수로교)이 어우러진 선종 사찰. 수로각 아치는 사진 명소로 유명하다.', '수로각 위로 올라가면 비와호 수로를 따라 걸을 수 있다.', NULL, 'https://nanzenji.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('덴류지', '天龍寺', 'SHRINE_TEMPLE', '京都府', '京都市右京区', 35.015778, 135.673745, 'FIXED', '08:30', '17:00', NULL, '마지막 입장 16:50', '정원 500엔', '아라시야마의 세계유산 선종 사찰. 산을 배경으로 한 소겐치 정원과 북문으로 이어지는 대나무숲이 함께 있다.', '북문으로 나가면 바로 대나무숲 길이다.', NULL, 'https://www.tenryuji.com/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('아라시야마 대나무숲 길', '嵐山 竹林の小径', 'PARK_GARDEN', '京都府', '京都市右京区', 35.017025, 135.671375, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '하늘까지 뻗은 대나무 사이로 약 400m 이어지는 산책길. 바람이 불면 댓잎 스치는 소리가 가득하다.', '낮엔 붐비니 아침 8시 전이 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도게쓰교', '渡月橋', 'VIEWPOINT', '京都府', '京都市右京区', 35.012888, 135.677795, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '가쓰라강을 가로지르는 아라시야마의 상징 다리. 산을 배경으로 봄 벚꽃, 가을 단풍이 그림처럼 펼쳐진다.', '강가 둑에 앉아 쉬기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('교토 교엔', '京都御苑', 'PARK_GARDEN', '京都府', '京都市上京区', 35.025430, 135.762100, 'ALWAYS', NULL, NULL, NULL, '공원은 상시 개방. 교토 고쇼(궁)는 별도 시간', NULL, '옛 궁궐 교토 고쇼를 둘러싼 넓은 국민공원. 자갈길과 큰 나무 사이로 한적하게 걷기 좋다.', '3월엔 매화, 4월엔 수양벚꽃이 핀다.', NULL, 'https://kyotogyoen.go.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('마루야마 공원', '円山公園', 'PARK_GARDEN', '京都府', '京都市東山区', 35.003800, 135.780800, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '야사카 신사 뒤편의 교토에서 가장 오래된 공원. 봄이면 커다란 기온 시다레자쿠라가 밤에도 불을 밝힌다.', '벚꽃철엔 꽃놀이 자리로 아주 붐빈다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('철학의 길', '哲学の道', 'PARK_GARDEN', '京都府', '京都市左京区', 35.023570, 135.794780, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '수로를 따라 긴카쿠지에서 난젠지 쪽까지 약 2km 이어지는 산책길. 철학자 니시다 기타로가 걸었다고 해서 붙은 이름.', '봄 벚꽃 터널, 가을 단풍이 특히 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('교토 타워', '京都タワー', 'VIEWPOINT', '京都府', '京都市下京区', 34.987528, 135.759306, 'FIXED', '10:00', '21:00', NULL, '마지막 입장 20:30', '900엔', '교토역 바로 앞에 선 등대 모양 전망 타워. 높이 100m 전망실에서 교토 시내와 주변 산이 한눈에 보인다.', '해 질 녘에 오르면 야경까지 이어서 볼 수 있다.', NULL, 'https://www.kyoto-tower.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('교토 수족관', '京都水族館', 'AMUSEMENT', '京都府', '京都市下京区', 34.987517, 135.747125, 'VARIES', NULL, NULL, NULL, '날짜에 따라 다름. 공식 사이트 확인', NULL, '교토역에서 걸어갈 수 있는 내륙형 수족관. 거대한 장수도롱뇽과 돌고래 공연이 인기다.', '바로 옆 우메코지 공원과 함께 돌아보기 좋다.', NULL, 'https://www.kyoto-aquarium.com/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('교토 철도박물관', '京都鉄道博物館', 'AMUSEMENT', '京都府', '京都市下京区', 34.987556, 135.743389, 'FIXED', '10:00', '17:00', 'WED', '마지막 입장 16:30. 공휴일·봄방학·여름방학엔 수요일도 개관', '1,500엔', '증기기관차부터 신칸센까지 실물 차량 50여 대가 모인 일본 최대급 철도 박물관. 실제로 달리는 증기기관차도 탈 수 있다.', '부채꼴 차고(선형차고)가 볼거리.', NULL, 'https://www.kyotorailwaymuseum.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('우메코지 공원', '梅小路公園', 'PARK_GARDEN', '京都府', '京都市下京区', 34.987500, 135.746000, 'ALWAYS', NULL, NULL, NULL, '공원 내 정원(스자쿠노니와)은 별도 시간', NULL, '교토역 서쪽의 넓은 잔디 공원. 수족관과 철도박물관이 붙어 있어 가족 나들이 코스로 좋다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('니조성', '二条城', 'HISTORIC', '京都府', '京都市中京区', 35.014167, 135.748111, 'FIXED', '08:45', '17:00', NULL, '마지막 입장 16:00. 12/29~31 휴무. 1·7·8·12월 화요일엔 니노마루 어전 관람만 중지', NULL, '도쿠가와 이에야스가 지은 교토의 성. 걸으면 새소리가 나는 니노마루 어전의 "꾀꼬리 마루"가 유명한 세계유산.', '어전 내부는 촬영 금지.', NULL, 'https://nijo-jocastle.city.kyoto.lg.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('기온 하나미코지', '祇園 花見小路', 'HISTORIC', '京都府', '京都市東山区', 35.002860, 135.775220, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '찻집과 요정이 늘어선 기온의 돌길 거리. 저녁이면 등불이 켜지고 운이 좋으면 마이코를 볼 수도 있다.', '사유지 골목 촬영 금지 표지가 있으니 지키자.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('산넨자카·니넨자카', '産寧坂・二寧坂', 'HISTORIC', '京都府', '京都市東山区', 34.996180, 135.781020, 'ALWAYS', NULL, NULL, NULL, '상점은 대개 저녁에 닫음', NULL, '기요미즈데라로 이어지는 옛 돌계단 언덕길. 전통 목조 상점과 찻집이 늘어서 교토다운 풍경이 이어진다.', '이른 아침엔 사람 없이 사진 찍기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('시모가모 신사', '下鴨神社', 'SHRINE_TEMPLE', '京都府', '京都市左京区', 35.038889, 135.772778, 'FIXED', '06:30', '17:00', NULL, '누문 안 기준. 경내 숲은 자유', NULL, '교토에서 가장 오래된 신사 중 하나인 세계유산. 원시림 다다스노모리를 지나 붉은 누문에 닿는다.', '인연을 맺어주는 아이오이샤도 경내에 있다.', NULL, 'https://www.shimogamo-jinja.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('기타노 텐만구', '北野天満宮', 'SHRINE_TEMPLE', '京都府', '京都市上京区', 35.031200, 135.735100, 'FIXED', '07:00', '17:00', NULL, '본전 앞 삼광문은 30분 일찍 닫음', NULL, '학문의 신 스가와라노 미치자네를 모신 신사. 매화 명소로, 2~3월에 경내 매화원이 문을 연다.', '매달 25일에 덴진상 장이 선다.', NULL, 'https://kitanotenmangu.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('료안지', '龍安寺', 'SHRINE_TEMPLE', '京都府', '京都市右京区', 35.034493, 135.718283, 'FIXED', '08:00', '17:00', NULL, '12~2월은 8:30~16:30', '600엔', '하얀 모래 위에 돌 15개를 놓은 석정으로 유명한 선종 사찰. 어느 자리에서 봐도 돌 하나가 가려진다고 한다.', '툇마루에 앉아 천천히 보는 게 묘미.', NULL, 'http://www.ryoanji.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오사카성 공원', '大阪城公園', 'PARK_GARDEN', '大阪府', '大阪市中央区', 34.687300, 135.526200, 'ALWAYS', NULL, NULL, NULL, '공원은 상시 개방', NULL, '오사카성 천수각을 둘러싼 넓은 공원. 해자와 석벽을 따라 걷기 좋고 봄에는 니시노마루 정원 벚꽃이 유명하다.', NULL, NULL, 'https://osakacastlepark.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오사카성 천수각', '大阪城天守閣', 'HISTORIC', '大阪府', '大阪市中央区', 34.687315, 135.525929, 'FIXED', '09:00', '18:00', NULL, '마지막 입장 17:30. 12/28~1/1 휴관', '1,200엔', '도요토미 히데요시가 쌓은 오사카성의 천수각. 안은 역사 박물관이고 꼭대기 전망대에서 시내가 보인다.', NULL, NULL, 'https://www.osakacastle.net/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('가이유칸', '海遊館', 'AMUSEMENT', '大阪府', '大阪市港区', 34.654475, 135.428967, 'VARIES', NULL, NULL, NULL, '날짜에 따라 다름. 공식 사이트 확인', NULL, '태평양을 재현한 거대한 수조에서 고래상어가 헤엄치는 세계 최대급 수족관. 건물 꼭대기부터 나선형으로 내려오며 본다.', '옆 덴포잔 대관람차와 같이 들르기 좋다.', NULL, 'https://www.kaiyukan.com/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('유니버설 스튜디오 재팬', 'ユニバーサル・スタジオ・ジャパン', 'AMUSEMENT', '大阪府', '大阪市此花区', 34.665442, 135.432338, 'VARIES', NULL, NULL, NULL, '날짜에 따라 다름. 공식 달력 확인', NULL, '영화 속 세계를 그대로 옮긴 테마파크. 닌텐도 월드와 해리 포터 구역이 특히 인기다.', '하루 종일 걸리니 코스엔 근처 식사 하나만 붙이자.', NULL, 'https://www.usj.co.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('쓰텐카쿠', '通天閣', 'VIEWPOINT', '大阪府', '大阪市浪速区', 34.652500, 135.506300, 'FIXED', '09:00', '22:00', NULL, '마지막 입장 21:30 (2026년 3월부터)', NULL, '신세카이 한가운데 선 오사카의 상징 타워. 전망대의 행운의 신 빌리켄 발바닥을 만지면 복이 온다고 한다.', NULL, NULL, 'https://www.tsutenkaku.co.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('하루카스 300', 'ハルカス300（あべのハルカス展望台）', 'VIEWPOINT', '大阪府', '大阪市阿倍野区', 34.645883, 135.513533, 'FIXED', '09:00', '22:00', NULL, '마지막 입장 21:30', '2,200엔 (2026년 7월부터)', '높이 300m 아베노 하루카스 꼭대기 전망대. 통유리 너머로 오사카 시내부터 날씨 좋으면 아카시 해협까지 보인다.', '해 질 녘 입장해서 야경까지 보는 게 인기.', NULL, 'https://www.abenoharukas-300.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('우메다 스카이빌딩 공중정원', '梅田スカイビル 空中庭園展望台', 'VIEWPOINT', '大阪府', '大阪市北区', 34.705278, 135.490556, 'FIXED', '09:30', '22:30', NULL, '마지막 입장 22:00', NULL, '두 빌딩을 꼭대기에서 잇는 원형 옥상 전망대. 지붕 없는 야외 회랑을 한 바퀴 돌며 오사카 야경을 볼 수 있다.', NULL, NULL, 'https://www.kuchu-teien.com/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('스미요시 대사', '住吉大社', 'SHRINE_TEMPLE', '大阪府', '大阪市住吉区', 34.612500, 135.493000, 'FIXED', '06:00', '17:00', NULL, '10~3월은 6:30부터. 바깥 문은 16:00에 닫음', NULL, '전국 스미요시 신사의 총본사. 가파르게 휜 붉은 다리 소리바시와 독특한 옛 건축 양식의 본전이 볼거리.', '소리바시는 경사가 급하니 천천히.', NULL, 'https://www.sumiyoshitaisha.net/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('시텐노지', '四天王寺', 'SHRINE_TEMPLE', '大阪府', '大阪市天王寺区', 34.653600, 135.516400, 'FIXED', '08:30', '16:30', NULL, '중심 가람 기준. 10~3월은 16:00까지. 문은 24시간 열려 있어 바깥 참배는 언제든', '중심 가람 500엔', '쇼토쿠 태자가 세웠다고 전해지는 일본에서 가장 오래된 관사 중 하나. 탑과 금당이 일직선으로 놓인 옛 가람 배치가 남아 있다.', '매달 21·22일에 경내에 장이 선다.', NULL, 'https://www.shitennoji.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도톤보리', '道頓堀', 'HISTORIC', '大阪府', '大阪市中央区', 34.668700, 135.501300, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '운하를 따라 거대한 간판과 네온이 늘어선 오사카 먹자 거리. 글리코 달리는 사람 간판 앞이 기념사진 명소.', '밤에 오면 네온이 운하에 비쳐 더 화려하다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('호젠지 요코초', '法善寺横丁', 'HISTORIC', '大阪府', '大阪市中央区', 34.668000, 135.502900, 'ALWAYS', NULL, NULL, NULL, '가게는 대개 저녁 영업', NULL, '도톤보리 바로 옆 돌바닥 골목. 이끼로 뒤덮인 미즈카케 부동명왕에 물을 끼얹고 소원을 비는 곳.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('신세카이', '新世界', 'HISTORIC', '大阪府', '大阪市浪速区', 34.652000, 135.506000, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '쓰텐카쿠 아래 쇼와 시대 분위기가 남은 번화가. 구시카쓰 가게와 레트로 간판이 빼곡하다.', '구시카쓰 소스는 한 번만 찍는 게 규칙.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('덴노지 동물원', '天王寺動物園', 'AMUSEMENT', '大阪府', '大阪市天王寺区', 34.651000, 135.508500, 'FIXED', '09:30', '17:00', 'MON', '마지막 입장 16:00. 5·9월 주말·공휴일은 18:00까지. 월요일이 공휴일이면 다음 날 휴무', '500엔', '도심 한가운데 있는 100년 넘은 동물원. 아프리카 사바나를 재현한 구역이 볼만하다.', NULL, NULL, 'https://www.tennojizoo.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나카노시마 공원', '中之島公園', 'PARK_GARDEN', '大阪府', '大阪市北区', 34.692500, 135.507000, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '두 강 사이 섬에 만든 오사카 최초의 공원. 장미 정원과 붉은 벽돌의 중앙공회당이 어우러진다.', '5월·10월 장미철이 가장 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오사카 텐만구', '大阪天満宮', 'SHRINE_TEMPLE', '大阪府', '大阪市北区', 34.695700, 135.512400, 'FIXED', '09:00', '17:00', NULL, NULL, NULL, '학문의 신을 모신 오사카의 덴진상. 일본 3대 축제 덴진 마쓰리의 무대이고, 옆으로 일본에서 가장 긴 상점가가 이어진다.', '덴진바시스지 상점가 군것질과 같이 돌기 좋다.', NULL, 'https://osakatemmangu.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('엑스포 70 기념공원', '万博記念公園', 'PARK_GARDEN', '大阪府', '吹田市', 34.809400, 135.532300, 'FIXED', '09:30', '17:00', 'WED', '마지막 입장 16:30. 4/1~5/2·10~11월은 무휴. 수요일이 공휴일이면 다음 날 휴무', NULL, '1970년 오사카 만국박람회장을 공원으로 만든 곳. 거대한 "태양의 탑"과 넓은 자연문화원이 있다.', '태양의 탑 내부 관람은 예약제.', NULL, 'https://www.expo70-park.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('스쿠나히코나 신사', '少彦名神社', 'SHRINE_TEMPLE', '大阪府', '大阪市中央区', 34.688493, 135.506077, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '제약회사가 모인 도쇼마치의 약의 신 신사. 빌딩 사이 작은 신사지만 병을 막는 종이 호랑이 부적으로 유명하다.', '11월 22~23일 신노사이 축제 때 가장 북적인다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도다이지', '東大寺', 'SHRINE_TEMPLE', '奈良県', '奈良市', 34.688983, 135.839793, 'FIXED', '07:30', '17:30', NULL, '대불전 기준. 11~3월은 8:00~17:00. 마지막 입장 30분 전', '800엔', '높이 약 15m의 노사나불(나라 대불)을 모신 세계 최대급 목조건물 대불전. 남대문의 금강역사상도 거대하다.', '대불전 기둥 구멍을 빠져나가면 복이 온다는 이야기가 있다.', NULL, 'https://www.todaiji.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('가스가 대사', '春日大社', 'SHRINE_TEMPLE', '奈良県', '奈良市', 34.681256, 135.848440, 'FIXED', '06:30', '17:30', NULL, '11~2월은 7:00~17:00. 회랑 안 특별 참배는 유료', NULL, '숲속 참배길에 석등롱 약 2000기와 처마의 청동 등롱 약 1000기가 늘어선 세계유산 신사.', '2월·8월 만등롱 행사 때는 모든 등불이 켜진다.', NULL, 'https://www.kasugataisha.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나라 공원', '奈良公園', 'PARK_GARDEN', '奈良県', '奈良市', 34.685100, 135.843000, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '사슴 천여 마리가 자유롭게 돌아다니는 넓은 공원. 도다이지·고후쿠지·가스가 대사가 모두 이 안에 있다.', '사슴 센베는 공원 안 판매대에서. 종이봉투는 사슴이 먹으니 조심.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('고후쿠지', '興福寺', 'SHRINE_TEMPLE', '奈良県', '奈良市', 34.683000, 135.831800, 'ALWAYS', NULL, NULL, NULL, '경내 자유. 국보관·중금당·동금당은 9:00~17:00', '국보관 700엔', '후지와라 가문의 절로 나라 공원 입구에 있다. 오층탑과 국보관의 아수라상이 유명하다.', NULL, NULL, 'https://www.kohfukuji.com/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나라마치', 'ならまち', 'HISTORIC', '奈良県', '奈良市', 34.677000, 135.829000, 'ALWAYS', NULL, NULL, NULL, '가게는 대개 저녁에 닫음', NULL, '에도~메이지 시대 상가 건물이 남은 옛 동네. 좁은 골목에 카페와 잡화점이 숨어 있다.', '처마 끝 빨간 원숭이 인형(미가와리자루)이 이 동네의 부적.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('와카쿠사야마', '若草山', 'VIEWPOINT', '奈良県', '奈良市', 34.686800, 135.852000, 'FIXED', '09:00', '17:00', NULL, '3월 셋째 토요일~12월 둘째 일요일만 입산 가능', '150엔', '잔디로 덮인 둥근 산. 정상에 오르면 나라 시내와 대불전 지붕이 내려다보인다.', '1월 넷째 토요일 산불 태우기(야마야키) 행사로 유명.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('이스이엔', '依水園', 'PARK_GARDEN', '奈良県', '奈良市', 34.685700, 135.837000, 'FIXED', '09:30', '16:30', 'TUE', '마지막 입장 16:00. 12월 말~1월 중순·9월 하순 정비 휴원', '1,200엔', '도다이지 남대문 지붕과 와카쿠사야마를 배경으로 끌어들인 차경 정원. 연못을 따라 천천히 걷는 회유식 정원이다.', '정원 안 찻집에서 말차를 마실 수 있다.', NULL, 'https://isuien.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('호류지', '法隆寺', 'SHRINE_TEMPLE', '奈良県', '生駒郡斑鳩町', 34.614300, 135.734600, 'FIXED', '08:00', '17:00', NULL, '11/4~2/21은 16:30까지', NULL, '현존하는 세계 최고(最古)의 목조건물군. 일본 최초의 세계유산으로 쇼토쿠 태자가 세웠다고 전해진다.', NULL, NULL, 'https://www.horyuji.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('야쿠시지', '薬師寺', 'SHRINE_TEMPLE', '奈良県', '奈良市', 34.668400, 135.784300, 'FIXED', '08:30', '17:00', NULL, '마지막 입장 16:30', NULL, '붉은 회랑 안에 동탑·서탑 두 탑이 마주 선 세계유산 사찰. 동탑은 나라 시대 그대로 남은 건물이다.', '근처 도쇼다이지와 걸어서 함께 돌 수 있다.', NULL, 'https://yakushiji.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도쇼다이지', '唐招提寺', 'SHRINE_TEMPLE', '奈良県', '奈良市', 34.675800, 135.784900, 'FIXED', '08:30', '17:00', NULL, '마지막 입장 16:30', NULL, '당나라 고승 감진이 세운 절. 나라 시대 금당이 그대로 남은 세계유산으로 고요한 분위기가 매력이다.', NULL, NULL, 'https://toshodaiji.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('헤이조 궁터', '平城宮跡', 'PARK_GARDEN', '奈良県', '奈良市', 34.691400, 135.795700, 'ALWAYS', NULL, NULL, NULL, '복원 건물·자료관은 별도 시간', NULL, '나라 시대 도읍의 궁궐 터. 복원된 대극전과 주작문 사이로 넓은 들판이 펼쳐진다.', '해 질 녘 들판에 지는 노을이 아름답다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('우키미도', '浮見堂', 'VIEWPOINT', '奈良県', '奈良市', 34.679500, 135.843000, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '사기이케 연못 위에 떠 있는 듯한 팔각 정자. 물에 비친 모습이 그림 같아 사진 명소로 꼽힌다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히메지성', '姫路城', 'HISTORIC', '兵庫県', '姫路市', 34.839449, 134.693906, 'FIXED', '09:00', '17:00', NULL, '마지막 입장 16:00. 4/27~8/31은 18:00까지. 12/29~30 휴무', '2,500엔 (2026년 3월부터, 히메지 시민 외)', '하얀 벽과 겹겹의 지붕이 백로를 닮아 "백로성"이라 불리는 일본 최초의 세계유산 성. 옛 천수각이 그대로 남아 있다.', '천수각 계단이 가파르니 편한 신발 필수.', NULL, 'https://www.city.himeji.lg.jp/castle/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('고코엔', '好古園', 'PARK_GARDEN', '兵庫県', '姫路市', 34.837800, 134.689300, 'FIXED', '09:00', '17:00', NULL, '마지막 입장 16:30. 4월 하순~8/31은 18:00까지', '310엔', '히메지성 서쪽 무사 저택 터에 만든 일본 정원. 담으로 나뉜 9개 정원을 차례로 걸으며 성을 바라볼 수 있다.', '히메지성 공통권이 있으면 더 싸다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('쇼샤잔 엔교지', '書寫山圓教寺', 'SHRINE_TEMPLE', '兵庫県', '姫路市', 34.889000, 134.662000, 'FIXED', '08:30', '17:00', NULL, '로프웨이 운행 시간 기준, 계절에 따라 연장', '500엔', '로프웨이로 오르는 산 위의 천년 사찰. 거대한 목조 건물 마니전과 숲속 3당이 장엄하다.', '영화 "라스트 사무라이" 촬영지.', NULL, 'https://www.shosha.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('구로카베 스퀘어', '黒壁スクエア', 'HISTORIC', '滋賀県', '長浜市', 35.379700, 136.270200, 'ALWAYS', NULL, NULL, NULL, '거리는 자유. 가게 영업시간은 가게마다 다름', NULL, '검은 벽의 옛 은행 건물을 중심으로 유리 공방과 가게가 모인 옛 거리. 나가하마 산책의 출발점이다.', NULL, NULL, 'https://www.kurokabe.co.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나가하마성 역사박물관', '長浜城歴史博物館', 'HISTORIC', '滋賀県', '長浜市', 35.375400, 136.262700, 'FIXED', '09:00', '17:00', 'MON', '마지막 입장 16:30. 월요일이 공휴일이면 다음 평일 휴관', '500엔', '도요토미 히데요시가 처음 성주가 된 나가하마성 자리에 세운 박물관. 꼭대기 전망실에서 비와호가 펼쳐진다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('호코엔', '豊公園', 'PARK_GARDEN', '滋賀県', '長浜市', 35.375000, 136.264000, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '나가하마성을 둘러싼 비와호 호숫가 공원. 봄이면 벚꽃 수백 그루가 성과 호수를 함께 물들인다.', '호숫가 노을이 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('다이쓰지', '大通寺', 'SHRINE_TEMPLE', '滋賀県', '長浜市', 35.382500, 136.270000, 'FIXED', '09:00', '16:30', NULL, '마지막 입장 16:00', '500엔', '"나가하마 고보"라 불리는 정토진종 사찰. 후시미성에서 옮겨왔다는 큰 본당이 옛 거리 끝에 있다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('구마노 나치 대사', '熊野那智大社', 'SHRINE_TEMPLE', '和歌山県', '東牟婁郡那智勝浦町', 33.668800, 135.890500, 'ALWAYS', NULL, NULL, NULL, '경내 자유', NULL, '구마노 3대 신사 중 하나. 467계단을 올라 닿는 산 중턱 신사로, 옆 세이간토지와 함께 세계유산이다.', '다이몬자카 돌계단길로 올라가면 옛 참배 기분이 난다.', NULL, 'https://kumanonachitaisha.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나치 폭포', '那智の滝', 'VIEWPOINT', '和歌山県', '東牟婁郡那智勝浦町', 33.675300, 135.887500, 'ALWAYS', NULL, NULL, NULL, '폭포는 언제든 볼 수 있음. 폭포 바로 앞 배소(무대)는 낮 시간·유료', '배소 300엔', '낙차 133m로 일본에서 한 줄기로 떨어지는 폭포 중 가장 높다. 폭포 자체가 신체로 모셔진다.', '세이간토지 삼층탑과 폭포가 한 화면에 들어오는 자리가 명당.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('세이간토지', '青岸渡寺', 'SHRINE_TEMPLE', '和歌山県', '東牟婁郡那智勝浦町', 33.668600, 135.889900, 'ALWAYS', NULL, NULL, NULL, '삼층탑 내부는 유료·낮 시간', NULL, '나치 대사 옆에 붙은 천태종 사찰. 붉은 삼층탑 뒤로 나치 폭포가 떨어지는 풍경이 유명하다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('다이몬자카', '大門坂', 'HISTORIC', '和歌山県', '東牟婁郡那智勝浦町', 33.664500, 135.890000, 'ALWAYS', NULL, NULL, NULL, NULL, NULL, '거대한 삼나무 숲 사이로 이어지는 구마노 고도의 돌계단길. 약 600m를 걸어 나치 대사로 오른다.', '이끼 낀 돌계단은 미끄러우니 조심.', NULL, NULL, DATE '2026-11-22', NULL);
